                n=n,
                started_at=started_at,
                ended_at=_now(),
                elapsed_s=round(time.monotonic() - t0, 3),
                request=dict(request_summary),
                http_status=status,
                outcome="ok" if kind is None else "service_failure",
                service_failure_kind=kind,
                raw_text=raw_text,
                envelope=envelope,
                error=error,
                response_body=response_body,
            )
        )
        if kind is None:
            return GenerateResult(attempts=attempts, ok=True, raw_text=raw_text, last_kind=None)
        if n < settings.max_attempts:
            sleep(settings.backoff_s[n - 1])
    return GenerateResult(attempts=attempts, ok=False, raw_text=None, last_kind=kind)

