"""HTTP transport, the Ollama generate client and the judge client.

Spec FR-020, FR-022, FR-023, FR-030; research.md R-9, R-11, R-12.

- All HTTP goes through an injectable `transport(method, url, body, timeout) -> (status, body)`.
  The default transport uses a hand-built `OpenerDirector` with only the four HTTP handlers, so
  `file:`, `ftp:` and `data:` URLs cannot be opened (bandit B310 mitigation, no `nosec`).
- Service failures are classified with the R-9 (rev 2) first-match table and retried: at most
  3 attempts, backoff 5 s then 10 s. Anything that is not a service failure propagates.
"""

from __future__ import annotations

import datetime
import http.client
import json
import time
import urllib.error
import urllib.request
from collections.abc import Callable
from dataclasses import asdict, dataclass, field

from . import config

Transport = Callable[[str, str, "bytes | None", float], tuple[int, bytes]]

SERVICE_KINDS = (
    "timeout",
    "unreachable",
    "connection_lost",
    "http_error",
    "empty_response",
    "bad_envelope",
)
ENVELOPE_KEYS = ("done_reason", "eval_count", "prompt_eval_count", "total_duration", "model")


class _HTTPOnlyOpener(urllib.request.OpenerDirector):
    """An OpenerDirector that refuses every scheme except http and https up front.

    A bare OpenerDirector returns None (not an error) for a scheme it has no handler for, so
    the refusal is made explicit here, before any handler or socket is involved.
    """

    def open(self, fullurl, data=None, timeout=None):
        url = fullurl.full_url if isinstance(fullurl, urllib.request.Request) else fullurl
        scheme = url.split(":", 1)[0].lower() if ":" in url else ""
        if scheme not in ("http", "https"):
            raise urllib.error.URLError(
                f"refused URL scheme {scheme or '(none)'!r}: only http/https"
            )
        return super().open(fullurl, data, timeout)


def build_opener() -> urllib.request.OpenerDirector:
    """An opener with only HTTPHandler, HTTPSHandler, HTTPDefaultErrorHandler, HTTPErrorProcessor."""
    opener = _HTTPOnlyOpener()
    for handler in (
        urllib.request.HTTPHandler(),
        urllib.request.HTTPSHandler(),
        urllib.request.HTTPDefaultErrorHandler(),
        urllib.request.HTTPErrorProcessor(),
    ):
        opener.add_handler(handler)
    return opener


def default_transport(method: str, url: str, body: bytes | None, timeout: float):
    """Perform the whole exchange, including reading the body, so that read-time errors
    (RemoteDisconnected, IncompleteRead, ...) surface here and are classified (R-9, E2)."""
    headers = {"Content-Type": "application/json"} if body is not None else {}
    request = urllib.request.Request(url, data=body, method=method, headers=headers)
    try:
        with build_opener().open(request, timeout=timeout) as response:
            return response.status, response.read()
    except urllib.error.HTTPError as exc:
        try:
            return exc.code, exc.read()
        finally:
            exc.close()


def classify_exception(exc: BaseException) -> str | None:
    """R-9 (rev 2) first-match table; `None` means "not a service failure"."""
    if isinstance(exc, TimeoutError) or (
        isinstance(exc, urllib.error.URLError) and isinstance(exc.reason, TimeoutError)
    ):
        return "timeout"
    if isinstance(exc, urllib.error.HTTPError):
        return "http_error"
    if isinstance(exc, urllib.error.URLError | ConnectionRefusedError):
        return "unreachable"
    if isinstance(exc, http.client.HTTPException | OSError):
        return "connection_lost"
    return None


class ServiceError(Exception):
    """A classified service failure from `get_json` / `post_json`."""

    def __init__(self, kind: str, detail: str):
        super().__init__(f"{kind}: {detail}")
        self.kind = kind
        self.detail = detail


def _now() -> str:
    return (
        datetime.datetime.now(datetime.UTC)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z")
    )


def _decode_object(body: bytes):
    """Return `(kind, obj, detail)` for a 2xx body: empty_response, bad_envelope or a dict."""
    if not body.strip():
        return "empty_response", None, "empty response body"
    try:
        obj = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        return "bad_envelope", None, f"body is not JSON: {exc}"
    if not isinstance(obj, dict):
        return "bad_envelope", None, f"body is a JSON {type(obj).__name__}, not an object"
    return None, obj, None


def _request_json(method, url, payload, timeout, transport):
    transport = transport or default_transport
    body = None if payload is None else json.dumps(payload).encode("utf-8")
    try:
        status, data = transport(method, url, body, timeout)
    except Exception as exc:
        kind = classify_exception(exc)
        if kind is None:
            raise
        raise ServiceError(kind, f"{type(exc).__name__}: {exc}") from exc
    if not 200 <= status < 300:
        raise ServiceError("http_error", f"HTTP {status}: {data[:200]!r}")
    kind, obj, detail = _decode_object(data)
    if kind is not None:
        raise ServiceError(kind, detail)
    return obj


def get_json(url: str, *, timeout: float, transport: Transport | None = None) -> dict:
    """GET a JSON object (pin check, R-11). Raises ServiceError on a service failure."""
    return _request_json("GET", url, None, timeout, transport)


def post_json(
    url: str, payload: dict, *, timeout: float, transport: Transport | None = None
) -> dict:
    """POST a JSON object and read a JSON object back. Raises ServiceError on a service failure."""
    return _request_json("POST", url, payload, timeout, transport)


# ------------------------------------------- generate --------------------------------------------


@dataclass
class Attempt:
    """One HTTP attempt (data-model.md Attempt). `response_body` is the verbatim body, stored in
    the raw evidence file only; `to_dict()` gives the summary without it."""

    n: int
    started_at: str
    ended_at: str
    elapsed_s: float
    request: dict
    http_status: int | None
    outcome: str
    service_failure_kind: str | None
    raw_text: str | None
    envelope: dict | None
    error: str | None = None
    response_body: str | None = field(default=None, repr=False)

    def to_dict(self) -> dict:
        data = asdict(self)
        del data["response_body"]
        return data


@dataclass
class GenerateResult:
    attempts: list[Attempt]
    ok: bool
    raw_text: str | None
    last_kind: str | None


def _interpret_generate(status: int, data: bytes):
    """Return `(kind, raw_text, envelope, error)` for one generate reply (R-9 rows 4-6)."""
    if not 200 <= status < 300:
        return "http_error", None, None, f"HTTP {status}: {data[:300].decode('utf-8', 'replace')}"
    kind, obj, detail = _decode_object(data)
    if kind is not None:
        return kind, None, None, detail
    envelope = {key: obj.get(key) for key in ENVELOPE_KEYS}
    if "response" not in obj or obj["response"] == "":
        return "empty_response", None, envelope, "response field missing or empty"
    if not isinstance(obj["response"], str):
        return "bad_envelope", None, envelope, "response field is not a string"
    return None, obj["response"], envelope, None


def generate(
    settings: config.Settings,
    system: str,
    prompt: str,
    *,
    transport: Transport | None = None,
    sleep: Callable[[float], None] = time.sleep,
) -> GenerateResult:
    """POST /api/generate with the pinned settings (FR-020), retrying service failures only."""
    transport = transport or default_transport
    url = settings.ollama_url.rstrip("/") + "/api/generate"
    options = {
        "temperature": settings.temperature,
        "num_predict": settings.num_predict,
        "num_ctx": config.num_ctx(len(system) + len(prompt)),
        "seed": settings.seed,
    }
    payload = {
        "model": settings.agent_model,
        "system": system,
        "prompt": prompt,
        "stream": False,
        "think": settings.think,
        "format": settings.format,
        "options": options,
    }
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request_summary = {
        "method": "POST",
        "url": url,
        "model": settings.agent_model,
        "stream": False,
        "think": settings.think,
        "format": settings.format,
        "options": dict(options),
        "timeout_s": settings.timeout_s,
    }
    attempts: list[Attempt] = []
    kind = None
    for n in range(1, settings.max_attempts + 1):
        started_at, t0 = _now(), time.monotonic()
        status = raw_text = envelope = error = response_body = None
        try:
            status, data = transport("POST", url, body, settings.timeout_s)
        except Exception as exc:
            kind = classify_exception(exc)
            if kind is None:
                raise
            error = f"{type(exc).__name__}: {exc}"
        else:
            response_body = data.decode("utf-8", "replace")
            kind, raw_text, envelope, error = _interpret_generate(status, data)
        attempts.append(
            Attempt(
                n=n,
                started_at=started_at,
                ended_at=_now(),
                elapsed_s=round(time.monotonic() - t0, 3),
                request=dict(request_summary),
                http_status=status,
                outcome="ok" if kind is None else "service_failure",
                service_failure_kind=kind,
                raw_text=raw_text,
                envelope=envelope,
                error=error,
                response_body=response_body,
            )
        )
        if kind is None:
            return GenerateResult(attempts=attempts, ok=True, raw_text=raw_text, last_kind=None)
        if n < settings.max_attempts:
            sleep(settings.backoff_s[n - 1])
    return GenerateResult(attempts=attempts, ok=False, raw_text=None, last_kind=kind)

"""Deterministic validators (research.md R-1, R-2, R-5 … R-7, R-17).

- A JSON Schema validator for exactly the keyword subset declared in R-1 (no dependency).
- `check_output`: the schema-1.0 contract (OUT-SCHEMA) plus the calendar-date check (OUT-DATE).

Every error is a `ValidationError(code, pointer, message, layer)`, with codes and layers from the
spec FR-028 table. Errors are collected, never stopped at the first.
"""

from __future__ import annotations

import copy
import datetime
import functools
import json
import re
from dataclasses import asdict, dataclass
from pathlib import Path

MR_VERSION = "mr-1"

ASSERTION_KEYWORDS = frozenset(
    {
        "type",
        "enum",
        "const",
        "properties",
        "required",
        "additionalProperties",
        "items",
        "minItems",
        "maxItems",
        "uniqueItems",
        "minLength",
        "pattern",
        "exclusiveMinimum",
        "maxProperties",
        "anyOf",
        "allOf",
        "if",
        "then",
        "$ref",
    }
)
ANNOTATION_KEYWORDS = frozenset({"$schema", "$id", "$defs", "title", "description", "$comment"})

_DATE_PATTERN = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


class UnsupportedKeyword(Exception):
    """A schema uses a keyword outside the R-1 subset, so the validator would ignore it."""


@dataclass(frozen=True)
class ValidationError:
    """One failed check. `keyword` is set for raw schema errors only."""

    code: str
    pointer: str
    message: str
    layer: int
    keyword: str = ""

    def to_dict(self) -> dict:
        data = asdict(self)
        del data["keyword"]
        return data


# ------------------------------------------ schema files ------------------------------------------


def schema_path(name: str) -> Path:
    """`schemas/<name>.schema.json`, resolved from the project root (editable install, R-2)."""
    return Path(__file__).resolve().parents[2] / "schemas" / f"{name}.schema.json"


@functools.cache
def _load_schema_cached(name: str) -> dict:
    return json.loads(schema_path(name).read_text(encoding="utf-8"))


def load_schema(name: str) -> dict:
    """A fresh copy of the named schema, so callers cannot change the cached one."""
    return copy.deepcopy(_load_schema_cached(name))


# ---------------------------------------- the R-1 validator ----------------------------------------


def _escape(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")


def _kind(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int | float):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    return type(value).__name__


def _json_equal(a, b) -> bool:
    """JSON equality: booleans are not numbers, 1 equals 1.0, containers compare deeply."""
    kind = _kind(a)
    if kind != _kind(b):
        return False
    if kind == "array":
        return len(a) == len(b) and all(_json_equal(x, y) for x, y in zip(a, b, strict=True))
    if kind == "object":
        return a.keys() == b.keys() and all(_json_equal(a[k], b[k]) for k in a)
    return a == b


def _is_type(value, name: str) -> bool:
    if name == "integer":
        return _kind(value) == "number" and float(value).is_integer()
    return _kind(value) == name


def _check_supported(schema, where: str = "#") -> None:
    """Walk the whole schema and refuse any keyword outside the R-1 subset."""
    if not isinstance(schema, dict):
        return
    for key, value in schema.items():
        if key not in ASSERTION_KEYWORDS and key not in ANNOTATION_KEYWORDS:
            raise UnsupportedKeyword(f"unsupported schema keyword {key!r} at {where}")
        if key == "$ref" and not (isinstance(value, str) and value.startswith("#")):
            raise UnsupportedKeyword(f"only local $ref is supported, got {value!r} at {where}")
        if key in ("properties", "$defs"):
            for sub_name, sub in value.items():
                _check_supported(sub, f"{where}/{key}/{sub_name}")
        elif key in ("items", "if", "then", "additionalProperties"):
            _check_supported(value, f"{where}/{key}")
        elif key in ("anyOf", "allOf"):
            for index, sub in enumerate(value):
                _check_supported(sub, f"{where}/{key}/{index}")


def _resolve(root: dict, ref: str) -> dict:
    node = root
    for token in ref[1:].split("/")[1:] if ref != "#" else []:
        node = node[token.replace("~1", "/").replace("~0", "~")]
    return node


def _pattern_matches(pattern: str, text: str) -> bool:
    # ECMA-262 `$` (no multiline) matches only at the very end, unlike Python's `$`, which also
    # matches before a final newline.
    if pattern.endswith("$") and not pattern.endswith("\\$"):
        pattern = pattern[:-1] + r"\Z"
    return re.search(pattern, text) is not None


class _Validator:
    def __init__(self, root: dict, code: str, layer: int):
        self.root = root
        self.code = code
        self.layer = layer

    def error(self, pointer: str, keyword: str, message: str) -> ValidationError:
        return ValidationError(self.code, pointer, message, self.layer, keyword)

    def run(self, value, schema, pointer: str) -> list[ValidationError]:
        if not isinstance(schema, dict):
            return []
        errors: list[ValidationError] = []
        if "$ref" in schema:
            errors += self.run(value, _resolve(self.root, schema["$ref"]), pointer)
        if "type" in schema:
            names = schema["type"] if isinstance(schema["type"], list) else [schema["type"]]
            if not any(_is_type(value, name) for name in names):
                errors.append(
                    self.error(
                        pointer, "type", f"expected {' or '.join(names)}, got {_kind(value)}"
                    )
                )
        if "enum" in schema and not any(_json_equal(value, item) for item in schema["enum"]):
            errors.append(
                self.error(pointer, "enum", f"{value!r} is not one of {schema['enum']!r}")
            )
        if "const" in schema and not _json_equal(value, schema["const"]):
            errors.append(self.error(pointer, "const", f"{value!r} is not {schema['const']!r}"))
        kind = _kind(value)
        if kind == "string":
            errors += self._string(value, schema, pointer)
        elif kind == "number":
            if "exclusiveMinimum" in schema and not value > schema["exclusiveMinimum"]:
                errors.append(
                    self.error(
                        pointer,
                        "exclusiveMinimum",
                        f"{value!r} is not > {schema['exclusiveMinimum']}",
                    )
                )
        elif kind == "array":
            errors += self._array(value, schema, pointer)
        elif kind == "object":
            errors += self._object(value, schema, pointer)
        if "anyOf" in schema and not any(
            not self.run(value, sub, pointer) for sub in schema["anyOf"]
        ):
            errors.append(self.error(pointer, "anyOf", "does not match any anyOf alternative"))
        for sub in schema.get("allOf", []):
            errors += self.run(value, sub, pointer)
        if "if" in schema and not self.run(value, schema["if"], pointer):
            errors += self.run(value, schema.get("then", {}), pointer)
        return errors

    def _string(self, value: str, schema: dict, pointer: str) -> list[ValidationError]:
        errors = []
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(
                self.error(pointer, "minLength", f"length {len(value)} < {schema['minLength']}")
            )
        if "pattern" in schema and not _pattern_matches(schema["pattern"], value):
            errors.append(
                self.error(pointer, "pattern", f"{value!r} does not match {schema['pattern']!r}")
            )
        return errors

    def _array(self, value: list, schema: dict, pointer: str) -> list[ValidationError]:
        errors = []
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(
                self.error(pointer, "minItems", f"{len(value)} items < {schema['minItems']}")
            )
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errors.append(
                self.error(pointer, "maxItems", f"{len(value)} items > {schema['maxItems']}")
            )
        if schema.get("uniqueItems"):
            for i, item in enumerate(value):
                if any(_json_equal(item, earlier) for earlier in value[:i]):
                    errors.append(self.error(f"{pointer}/{i}", "uniqueItems", "duplicate item"))
        if "items" in schema:
            for i, item in enumerate(value):
                errors += self.run(item, schema["items"], f"{pointer}/{i}")
        return errors

    def _object(self, value: dict, schema: dict, pointer: str) -> list[ValidationError]:
        errors = []
        properties = schema.get("properties", {})
        for key in schema.get("required", []):
            if key not in value:
                errors.append(self.error(pointer, "required", f"missing required key {key!r}"))
        if "maxProperties" in schema and len(value) > schema["maxProperties"]:
            errors.append(
                self.error(
                    pointer, "maxProperties", f"{len(value)} keys > {schema['maxProperties']}"
                )
            )
        for key, item in value.items():
            child = f"{pointer}/{_escape(key)}"
            if key in properties:
                errors += self.run(item, properties[key], child)
            elif schema.get("additionalProperties") is False:
                errors.append(self.error(child, "additionalProperties", f"unexpected key {key!r}"))
            elif isinstance(schema.get("additionalProperties"), dict):
                errors += self.run(item, schema["additionalProperties"], child)
        return errors


def validate(instance, schema: dict, *, code: str = "SCHEMA", layer: int = 1):
    """Validate `instance` against `schema` (R-1 subset). Returns every error found.

    Raises `UnsupportedKeyword` if the schema uses a keyword outside the subset.
    """
    _check_supported(schema)
    return _Validator(schema, code, layer).run(instance, schema, "")


# ------------------------------------------- output 1.0 -------------------------------------------


def check_output(result) -> list[ValidationError]:
    """OUT-SCHEMA (schema 1.0 incl. FR-015 shapes) and OUT-DATE (calendar date), both layer 1."""
    errors = validate(result, _load_schema_cached("output"), code="OUT-SCHEMA", layer=1)
    date = result.get("announcement_date") if isinstance(result, dict) else None
    if isinstance(date, str) and _DATE_PATTERN.fullmatch(date):
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            errors.append(
                ValidationError(
                    "OUT-DATE", "/announcement_date", f"{date!r} is not a calendar date", 1
                )
            )
    return errors

"""The evaluation dataset `evals/dataset.json` (spec FR-024, FR-025, FR-026, FR-035; data-model.md
DG-1 … DG-9). Checked independently of `.harness/run_eval.py`."""

from __future__ import annotations

import base64
import hashlib
import json
import re
from decimal import ROUND_HALF_UP, Decimal

import pytest
from conftest import DATA_MODEL_PATH, DATASET_PATH, SPEC_PATH

CATEGORIES = {
    "normal_single_order",
    "unit_crore",
    "unit_lakh",
    "unit_million",
    "multiple_orders",
    "multiple_orders_mixed_units",
    "ambiguous_value",
    "ambiguous_non_order",
    "missing_value",
    "missing_client",
    "non_order_results",
    "non_order_board_meeting",
    "malformed_empty",
    "malformed_whitespace",
    "malformed_garbled",
    "malformed_too_long",
    "injection_order",
    "injection_non_order",
    "edge_case",
    "owner_decision",
}
CASE_KEYS = {
    "id",
    "title",
    "categories",
    "input",
    "ground_truth",
    "expected_properties",
    "covers",
    "provenance",
}
EXPECTED_PROPERTY_KEYS = {"invariants", "rejection_reason", "injection", "checks"}
TOP_FIELDS = (
    "company",
    "announcement_date",
    "order_value",
    "currency",
    "unit",
    "client",
    "order_type",
    "execution_period",
)
ORDER_FIELDS = ("order_value", "currency", "unit", "client", "order_type", "execution_period")
ADDITIONAL_EVIDENCE_FIELDS = ("order_value", "currency", "unit", "client")

# FR-009 unit factors, for this test's own FR-035 recomputation (no import from validators).
UNIT_FACTOR = {
    "crore": 10_000_000,
    "lakh": 100_000,
    "million": 1_000_000,
    "billion": 1_000_000_000,
    "thousand": 1_000,
    "absolute": 1,
}


def _dataset():
    return json.loads(DATASET_PATH.read_text(encoding="utf-8"))


def _cases():
    return {case["id"]: case for case in _dataset()["cases"]}


def _ws(text):
    return re.sub(r"\s+", " ", text).strip()


def _expand(input_spec) -> bytes:
    kind = input_spec["kind"]
    if kind == "text":
        return input_spec["text"].encode("utf-8")
    if kind == "base64":
        return base64.b64decode(input_spec["data"], validate=True)
    text = input_spec["text"]
    while len(text) < input_spec["length"]:
        text += input_spec["filler"]
    return text[: input_spec["length"]].encode("utf-8")


def _orders(gt):
    if gt["order"] is None:
        return []
    return [gt["order"], *gt["additional_orders"]]


def _expected_value_in_cr(order):
    if order["currency"] != "INR":
        return None
    multiplier = Decimal(UNIT_FACTOR[order["unit"]]) / Decimal(UNIT_FACTOR["crore"])
    exact = Decimal(str(order["order_value"])) * multiplier
    return exact.quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)


def _canon_digits(value):
    return format(Decimal(str(value)).normalize(), "f").replace(".", "").lstrip("-")


def _table_rows(text, heading_start):
    """Rows of the first Markdown table after the line starting with `heading_start`."""
    lines = text.splitlines()
    start = next(i for i, line in enumerate(lines) if line.startswith(heading_start))
    rows = []
    in_table = False
    for line in lines[start + 1 :]:
        if line.startswith("|"):
            in_table = True
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if not set(cells[0]) <= set("-"):
                rows.append(cells)
        elif in_table:
            break
    return rows[1:]  # drop the header row


def _expand_ids(cell):
    ids = []
    for part in cell.split(","):
        part = part.strip()
        match = re.fullmatch(r"([A-Z])(\d{2})–[A-Z](\d{2})", part)
        if match:
            ids += [f"{match[1]}{n:02d}" for n in range(int(match[2]), int(match[3]) + 1)]
        else:
            ids.append(part)
    return ids


def _planned():
    rows = _table_rows(DATA_MODEL_PATH.read_text(encoding="utf-8"), "### Planned cases")
    planned = {}
    for row in rows:
        assert len(row) == 6, row
        planned[row[0]] = {
            "categories": [c.strip() for c in row[2].split(",")],
            "covers": set(re.findall(r"FR-\d{3}|AC-\d\.\d", row[4])),
        }
    return planned


def _planned_value_in_cr():
    rows = _table_rows(
        DATA_MODEL_PATH.read_text(encoding="utf-8"), "Ground-truth `value_in_cr` per case"
    )
    table = {}
    for case_cell, top_cell, extra_cell in rows:
        if top_cell.startswith("no order object"):
            value = None
        else:
            top = re.match(r"(null|\d+(?:\.\d+)?)", top_cell)
            assert top, f"unparseable top-level cell {top_cell!r}"
            extras = []
            if extra_cell != "—":
                for part in re.split(r",\s*(?![^()]*\))", extra_cell):
                    number = re.match(r"(null|\d+(?:\.\d+)?)", part.strip())
                    assert number, f"unparseable additional cell {extra_cell!r}"
                    extras.append(number[1])
            value = [top[1], *extras]
        for case_id in _expand_ids(case_cell):
            table[case_id] = value
    return table


def _num(text):
    return None if text == "null" else Decimal(text)


