        assert len(covers["fr"]) == len(set(covers["fr"]))
        assert len(covers["ac"]) == len(set(covers["ac"]))
        covered |= set(covers["ac"])
    required = {
        f"AC-{s}.{n}" for s, last in ((1, 6), (2, 6), (3, 6), (4, 3)) for n in range(1, last + 1)
    }
    assert required <= covered


